import { clamp } from '../core/math.ts';
import { O, OFFROAD_BASE, carBase } from '../simulation/protocol.ts';

/** Airborne and landing cues (D047/D048 audio, WP41): read from the recorded
 * off-road block, so live play and replays sound the same. A machine in the
 * air has no tyre resisting its drive: the engine note unloads (the harmonic
 * bands and the brightness that follow load fall away while the revs, which
 * the simulation lets flare on the free-spinning wheel, keep tracking the
 * throttle). On touchdown a suspension thump scales with the impact speed. */

/** Share of the measured engine load an airborne machine's voice keeps. */
export const AIRBORNE_LOAD = 0.25;
/** Is entrant `id` airborne in this snapshot (O.AIRBORNE: dirt bikes and
 * cars on terrain venues; zero on paved circuits)? */
export function airborneAt(frame: Float32Array, id: number) {
  return frame[carBase(id) + OFFROAD_BASE + O.AIRBORNE] > 0.5;
}
/** Engine load multiplier for the voice of entrant `id`. */
export function engineUnload(frame: Float32Array, id: number) {
  return airborneAt(frame, id) ? AIRBORNE_LOAD : 1;
}
/** Landing thump gain for a touchdown at `impact` m/s (normal speed): a soft
 * roll-in is a murmur, a flat 6-7 m/s case landing a full-scale thud. */
export function landingThump(impact: number) {
  if (!Number.isFinite(impact) || impact <= 0.4) return 0;
  return 0.6 * clamp((impact - 0.4) / 6.5, 0, 1) ** 1.2;
}
/** The thump's length (s): heavier landings ring longer through the chassis. */
export const landingDuration = (impact: number) => 0.1 + 0.2 * clamp(impact / 7, 0, 1);

inputs.src/audio/engine-voices.ts:
import { F, carBase } from '../simulation/protocol.ts';
import { clamp } from '../core/math.ts';
import { SpatialAudioScene, type AudioView } from './spatial.ts';
import { engineUnload } from './airborne-audio.ts';
import {
  SOUND_PROFILES,
  frameCharacter,
  type SoundFamily,
  type SoundProfile,
} from './sound-profiles.ts';
import {
  BAND_MULTIPLIER,
  EV_IDLE_HUM_HZ,
  bandHarmonics,
  designedEngineLevel,
  designedMotorLevel,
  loudnessScale,
} from './engine-loudness.ts';
import { dbToGain } from './mixer.ts';
import { limiterFlutter, type LimiterFlutter } from './limiter-cue.ts';

/** K-weighted RMS amplitude a full-load redline voice presents before the buses
 * (the anchor of the designed loudness curve; set from rig measurements). */
export const ENGINE_REFERENCE_RMS = 0.07;
interface Voice {
  id: number;
  family: SoundFamily | null;
  osc: OscillatorNode[];
  bands: GainNode[];
  /** Fuel-cut bounce on the rev and pit limiters (limiter-cue.ts): `cut` carries
   * the steady part, `bounce` the LFO swing. */
  cut: GainNode;
  bounce: GainNode;
  filter: BiquadFilterNode;
  gain: GainNode;
  pan: StereoPannerNode;
}
/** Actual production graph, also executable by OfflineAudioContext. All four
 * engines use original harmonic bands; spatial motion controls their frequency,
 * attenuation and stereo image. Voice reassignment dips gain before retuning. */
export class EngineVoices {
  readonly spatial = new SpatialAudioScene();
  /** 0..1 loudness of the engines the listener hears right now (distance and the
   * designed level together): the ambience bed ducks under it. */
  presence = 0;
  private voices: Voice[] = [];
  private disposed = false;
  private waves = new Map<SoundFamily, PeriodicWave[]>();
  /** One shared bounce LFO: a smoothed square wave. */
  private lfo: OscillatorNode;
  private flutter: LimiterFlutter = { depth: 0, rateHz: 12 };
  constructor(
    private context: BaseAudioContext,
    destination: AudioNode = context.destination,
  ) {
    this.lfo = context.createOscillator();
    const real = new Float32Array(16),
      imag = new Float32Array(16);
    for (let k = 1; k < 16; k += 2) imag[k] = 1 / k ** 1.5;
    this.lfo.setPeriodicWave(context.createPeriodicWave(real, imag));
    this.lfo.frequency.value = 12;
    this.lfo.start();
    for (let i = 0; i < 4; i++) {
      const gain = context.createGain(),
        cut = context.createGain(),
        bounce = context.createGain(),
        filter = context.createBiquadFilter(),
        pan = context.createStereoPanner();
      gain.gain.value = 0;
      cut.gain.value = 1;
      bounce.gain.value = 0;
      this.lfo.connect(bounce).connect(cut.gain);
      filter.type = 'lowpass';
      filter.frequency.value = 2200;
      filter.Q.value = 0.5;
      gain.connect(cut).connect(filter).connect(pan).connect(destination);
      const osc: OscillatorNode[] = [],
        bands: GainNode[] = [];
      for (let j = 0; j < 3; j++) {
        const o = context.createOscillator(),
          g = context.createGain();
        g.gain.value = 0;
        o.connect(g).connect(gain);
        osc.push(o);
        bands.push(g);
      }
      this.voices.push({ id: -1, family: null, osc, bands, cut, bounce, filter, gain, pan });
    }
    for (const voice of this.voices) {
      this.assign(voice, SOUND_PROFILES['v6-turbo-hybrid']);
      for (const o of voice.osc) o.start();
    }
  }
  /** Harmonic spectrum per band from the family brief (odd/third emphasis, roll-off). */
  private wavesFor(profile: SoundProfile) {
    let waves = this.waves.get(profile.family);
    if (!waves) {
      waves = BAND_MULTIPLIER.map((_, band) => {
        const real = new Float32Array(40),
          imag = bandHarmonics(profile, band as 0 | 1 | 2);
        return this.context.createPeriodicWave(real, imag);
      });
      this.waves.set(profile.family, waves);
    }
    return waves;
  }
  private assign(voice: Voice, profile: SoundProfile) {
    if (voice.family === profile.family) return;
    const waves = this.wavesFor(profile);
    for (let j = 0; j < 3; j++) voice.osc[j].setPeriodicWave(waves[j]);
    voice.family = profile.family;
  }
  update(frame: Float32Array, view: AudioView, time: number) {
    if (this.disposed) return;
    if (!Number.isFinite(time) || time < 0) throw new Error('Invalid engine audio timestamp');
    this.spatial.update(frame, view);
    let presence = 0,
      bounceDepth = 0,
      bounceRate = 12;
    for (let i = 0; i < this.voices.length; i++) {
      const voice = this.voices[i],
        state = this.spatial.voices[i],
        id = state.id;
      if (id < 0) {
        voice.gain.gain.setTargetAtTime(0, time, 0.02);
        voice.id = -1;
        continue;
      }
      const o = carBase(id),
        rpm = frame[o + F.RPM];
      if (!Number.isFinite(rpm + frame[o + F.ENGINE_TORQUE]))
        throw new Error('Invalid engine audio state');
      const character = frameCharacter(frame, id),
        p = character.profile,
        limiter = character.limiterRPM;
      // In the air nothing resists the drive: the note unloads (D047).
      const load =
        clamp(Math.abs(frame[o + F.ENGINE_TORQUE]) / character.loadTorque, 0, 1) *
        engineUnload(frame, id);
      const changed = voice.id !== id || voice.family !== p.family,
        at = changed ? time + 0.02 : time;
      if (changed) {
        voice.gain.gain.cancelScheduledValues(time);
        voice.gain.gain.setTargetAtTime(0, time, 0.003);
        this.assign(voice, p);
      }
      // Electric families have no firing order: the voice follows motor speed, with
      // a faint inverter hum at a standstill so a stopped electric car is not silent.
      const electric = p.firingsPerRev === 0,
        road = Math.max(0, frame[o + F.SPEED]);
      const signature = character.signature;
      const cutoff =
        (view.interior && id === view.followedCar ? 1500 + load * 2300 : 2500 + load * 4600) *
        signature.brightness;
      const tilt = [dbToGain(signature.tiltDb / 2), 1, dbToGain(-signature.tiltDb / 2)] as const;
      const base = electric
        ? Math.max(EV_IDLE_HUM_HZ, road * p.motorHzPerMS * 0.25)
        : (rpm / 60) * p.firingsPerRev;
      const hz: [number, number, number] = [0, 0, 0],
        shape: [number, number, number] = [0, 0, 0];
      for (let band = 0; band < 3; band++) {
        hz[band] = Math.max(50, base * BAND_MULTIPLIER[band]) * state.doppler;
        const weight = electric
          ? band === 1
            ? 1
            : 0
          : Math.exp(-(((rpm - p.bandCentres[band] * limiter) / (p.bandWidth * limiter)) ** 2)) *
            (band === 0 ? 1 + p.burble * (1 - clamp(rpm / limiter, 0, 1)) : 1);
        shape[band] = weight * (electric ? p.motorGain * 4 : p.bandGain[band] * tilt[band]);
      }
      // The band weights fix the timbre; the designed curve fixes how loud it is.
      const level = electric ? designedMotorLevel(road) : designedEngineLevel(rpm / limiter, load);
      const scale = loudnessScale(
        p,
        hz,
        shape,
        cutoff,
        ENGINE_REFERENCE_RMS * level * dbToGain(p.levelDb),
      );
      for (let band = 0; band < 3; band++) {
        const frequency = voice.osc[band].frequency;
        if (changed) {
          frequency.cancelScheduledValues(at);
          frequency.setValueAtTime(hz[band], at);
        } else frequency.setTargetAtTime(hz[band], at, 0.035);
        voice.bands[band].gain.setTargetAtTime(shape[band] * scale, at, 0.04);
      }
      presence = Math.max(presence, (state.gain / 0.82) * level);
      // Rev limiter / pit limiter: the note bounces (limiter-cue.ts).
      limiterFlutter(frame, id, electric ? 0 : limiter, this.flutter);
      voice.cut.gain.setTargetAtTime(1 - this.flutter.depth / 2, at, 0.03);
      voice.bounce.gain.setTargetAtTime(this.flutter.depth / 2, at, 0.03);
      if (this.flutter.depth > bounceDepth) {
        bounceDepth = this.flutter.depth;
        bounceRate = this.flutter.rateHz;
      }
      voice.gain.gain.setTargetAtTime(state.gain, at, 0.03);
      voice.pan.pan.setTargetAtTime(state.pan, at, 0.025);
      voice.filter.frequency.setTargetAtTime(cutoff, at, 0.04);
      voice.id = id;
    }
    this.presence = presence;
    this.lfo.frequency.setTargetAtTime(bounceRate, time, 0.05);
  }
  dispose() {
    if (this.disposed) return;
    this.disposed = true;
    for (const voice of this.voices) {
      for (const osc of voice.osc) {
        osc.stop();
        osc.disconnect();
      }
      for (const band of voice.bands) band.disconnect();
      voice.cut.disconnect();
      voice.bounce.disconnect();
      voice.gain.disconnect();
      voice.filter.disconnect();
      voice.pan.disconnect();
    }
    this.lfo.stop();
    this.lfo.disconnect();
    this.voices.length = 0;
  }
}

inputs.src/audio/limiter-cue.ts:
import { clamp } from '../core/math.ts';
import { F, carBase } from '../simulation/protocol.ts';

/** Rev-limiter and pit-limiter flutter. A combustion engine on its limiter cuts
 * fuel in bursts: the note bounces. The first rig run found nothing of the kind:
 * the voice simply held its top note, so the player had no audible cue to shift
 * and the pit limiter (the HUD's PIT LIMITER state) was silent. Both are pure
 * functions of the recorded snapshot, so a replay bounces on the same frames. */
export interface LimiterFlutter {
  /** 0 (steady) to 1: how deep the gain bounces. */
  depth: number;
  /** Bounce rate (Hz). */
  rateHz: number;
}

/** Revs within this of the limiter count as "on the limiter". */
export const LIMITER_BAND_RPM = 60;
export const REV_LIMITER_RATE_HZ = 12;
export const PIT_LIMITER_RATE_HZ = 6;
/** Deepest bounce (fraction of the voice gain the cut removes). */
export const REV_LIMITER_DEPTH = 0.6;
export const PIT_LIMITER_DEPTH = 0.45;

/** The pit-lane limiter is on in the entry and exit phases (the HUD's rule, ui/interface.ts). */
export function pitLimiterOn(frame: Float32Array, car: number): boolean {
  const o = carBase(car),
    phase = frame[o + F.PIT_PHASE];
  return frame[o + F.IN_PIT] > 0 && (phase === 1 || phase === 6);
}

export function limiterFlutter(
  frame: Float32Array,
  car: number,
  limiterRPM: number,
  out: LimiterFlutter = { depth: 0, rateHz: REV_LIMITER_RATE_HZ },
): LimiterFlutter {
  const o = carBase(car),
    rpm = frame[o + F.RPM],
    throttle = frame[o + F.THROTTLE],
    gear = frame[o + F.GEAR];
  out.depth = 0;
  out.rateHz = REV_LIMITER_RATE_HZ;
  if (!Number.isFinite(rpm + throttle + gear)) return out;
  if (pitLimiterOn(frame, car) && frame[o + F.SPEED] > 4) {
    out.depth = PIT_LIMITER_DEPTH;
    out.rateHz = PIT_LIMITER_RATE_HZ;
  }
  // On the rev limiter with the throttle down: the cut flutters harder than the pit limiter.
  if (limiterRPM > 0 && rpm >= limiterRPM - LIMITER_BAND_RPM && throttle > 0.6 && gear > 0) {
    const into = clamp((rpm - (limiterRPM - LIMITER_BAND_RPM)) / LIMITER_BAND_RPM, 0, 1);
    out.depth = Math.max(out.depth, REV_LIMITER_DEPTH * (0.6 + 0.4 * into));
    out.rateHz = REV_LIMITER_RATE_HZ;
  }
  return out;
}

inputs.src/audio/mixer.ts:
import { clamp } from '../core/math.ts';

/** Gain staging for the race audio graph: the per-bus levels the player controls,
 * the calibrated trims between buses, the master bus (damp-air low-pass, bus
 * compressor, make-up gain, soft ceiling) and the control-rate maths (ducking,
 * smoothing). The numbers are NOT taste: every trim and the ceiling were set
 * from rig measurements (scripts/studio/tools/audio-render.mjs, see
 * docs/studio/reports/audio.md). Pure parts are unit-tested in tests/audio-mixer.test.ts. */

export const BUS_NAMES = ['engine', 'effects', 'ambience', 'ui', 'music'] as const;
export type BusName = (typeof BUS_NAMES)[number];
/** The player's bus sliders, 0..1. 1 is the mix as designed; the master is the
 * separate `Settings.volume`. */
export type AudioLevels = Record<BusName, number>;
export const DEFAULT_LEVELS: Readonly<AudioLevels> = Object.freeze({
  engine: 1,
  effects: 1,
  ambience: 1,
  ui: 1,
  music: 0.8,
});

export function validateLevels(value: unknown): AudioLevels {
  const source = value && typeof value === 'object' ? (value as Partial<AudioLevels>) : {};
  const out = { ...DEFAULT_LEVELS } as AudioLevels;
  for (const bus of BUS_NAMES) {
    const v = source[bus];
    if (typeof v === 'number' && Number.isFinite(v)) out[bus] = clamp(v, 0, 1);
  }
  return out;
}

export const dbToGain = (db: number) => 10 ** (db / 20);
export const gainToDb = (gain: number) => 20 * Math.log10(Math.max(gain, 1e-9));
/** Slider position to amplitude: a square-law taper, so half way is -12 dB and
 * the lower half of the slider is not dead weight. 0 is silence. */
export const sliderGain = (position: number) => clamp(position, 0, 1) ** 2;

/** The staging constants. `trimDb` balances the buses against each other at
 * slider positions of 1; `makeupDb` lifts the whole mix before the ceiling. */
export const GAIN_STAGING = Object.freeze({
  /** The master `volume` slider scale used since the first audio pass. */
  masterScale: 0.8,
  makeupDb: 9,
  ceilingDbfs: -1.5,
  trimDb: Object.freeze({
    engine: 0,
    effects: -6,
    ambience: -8,
    ui: 0,
    music: -3,
  } satisfies Record<BusName, number>),
  /** Ambience falls by this much while the engine is at full presence. */
  ambienceDuckDb: 8,
});

/** The gain of one bus: its trim times the player's slider. */
export function busGain(bus: BusName, levels: Readonly<AudioLevels>): number {
  return dbToGain(GAIN_STAGING.trimDb[bus]) * sliderGain(levels[bus]);
}

/** Master gain from the volume setting (linear amplitude as the setting has always been). */
export const masterGain = (volume: number, ambienceMaster = 1) =>
  clamp(volume, 0, 1) * GAIN_STAGING.masterScale * ambienceMaster;

/** Exponential approach of `current` to `target` over `dt` s with time constant `tau`. */
export function smoothToward(current: number, target: number, dt: number, tau: number): number {
  if (!(dt > 0) || !(tau > 0)) return target;
  return target + (current - target) * Math.exp(-dt / tau);
}

/** Linear gain applied to the ambience under the engine: 1 when the engine is
 * absent, `1 - (1 - 10^(-depthDb/20))` at full presence, with a smooth knee. */
export function duckGain(
  enginePresence: number,
  depthDb: number = GAIN_STAGING.ambienceDuckDb,
): number {
  const x = clamp((enginePresence - 0.15) / 0.6, 0, 1),
    smooth = x * x * (3 - 2 * x);
  return 1 - smooth * (1 - dbToGain(-Math.abs(depthDb)));
}

/** The static curve of the ceiling: identity up to the knee, then a tanh roll-off
 * that approaches (and never reaches) `ceiling`; odd-symmetric and monotone. */
export function softLimit(x: number, ceiling: number, knee = 0.6): number {
  const a = Math.abs(x);
  if (a <= knee) return x;
  const y = knee + (ceiling - knee) * Math.tanh((a - knee) / (ceiling - knee));
  return x < 0 ? -y : y;
}
/** WaveShaper table over [-1, 1]; inputs beyond clamp to the end values, which
 * are below the ceiling, so nothing leaves the shaper above it. */
export function softLimitCurve(
  ceiling: number,
  size = 4097,
  knee = 0.6,
): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(size);
  for (let i = 0; i < size; i++) curve[i] = softLimit((i / (size - 1)) * 2 - 1, ceiling, knee);
  return curve;
}

/** The bus a whole race mix passes through: damp-air low-pass (fog and snow close
 * it), a bus compressor that glues the layers, make-up gain, and a soft ceiling
 * so that no combination of sources can leave the context above -1 dBFS. */
export class MasterBus {
  readonly input: BiquadFilterNode;
  readonly compressor: DynamicsCompressorNode;
  readonly makeup: GainNode;
  readonly shaper: WaveShaperNode;
  private bypassed = false;
  constructor(
    context: BaseAudioContext,
    private readonly destination: AudioNode = context.destination,
  ) {
    // Damp air hushes the world: a master low-pass that fog closes (open at 18 kHz otherwise).
    this.input = context.createBiquadFilter();
    this.input.type = 'lowpass';
    this.input.frequency.value = 18000;
    this.input.Q.value = 0.5;
    this.compressor = context.createDynamicsCompressor();
    this.compressor.threshold.value = -20;
    this.compressor.knee.value = 12;
    this.compressor.ratio.value = 4;
    this.compressor.attack.value = 0.005;
    this.compressor.release.value = 0.2;
    this.makeup = context.createGain();
    this.makeup.gain.value = dbToGain(GAIN_STAGING.makeupDb);
    this.shaper = context.createWaveShaper();
    this.shaper.curve = softLimitCurve(dbToGain(GAIN_STAGING.ceilingDbfs));
    this.shaper.oversample = '4x';
    this.connect();
  }
  /** The final node: capture or analyse the mix here. */
  get output(): AudioNode {
    return this.bypassed ? this.makeup : this.shaper;
  }
  private connect() {
    this.input.disconnect();
    this.makeup.disconnect();
    this.compressor.disconnect();
    this.shaper.disconnect();
    if (this.bypassed) {
      this.input.connect(this.makeup);
      this.makeup.connect(this.destination);
    } else {
      this.input.connect(this.compressor);
      this.compressor.connect(this.makeup);
      this.makeup.connect(this.shaper);
      this.shaper.connect(this.destination);
    }
  }
  /** Diagnostic: take the compressor and ceiling out of the path (pre-limiter stem measurements). */
  bypassDynamics(on: boolean) {
    if (this.bypassed === on) return;
    this.bypassed = on;
    this.connect();
  }
  dispose() {
    for (const node of [this.input, this.compressor, this.makeup, this.shaper]) node.disconnect();
  }
}

inputs.src/audio/sound-profiles.ts:
import { RACE_BASE, R, carBase } from '../simulation/protocol.ts';
import { vehicleAt, type VehicleDefinition } from '../simulation/vehicles.ts';

/** Powertrain sound families (masterplan §20.2, WP26). Each family is an
 * original synthesis brief — firing order, harmonic emphasis, rev range,
 * induction and transmission character — never a recording. A vehicle picks
 * its family by id; unknown vehicles fall back by class and hybrid flag. */
export type SoundFamily =
  | 'v6-turbo-hybrid'
  | 'i4-turbo'
  | 'v8-na'
  | 'v8-crossplane-turbo'
  | 'v10-na'
  | 'v12-na'
  | 'flat6-na'
  | 'i4-na'
  | 'v4-bike'
  | 'i4-bike'
  | 'single-mx'
  | 'two-stroke-kart'
  | 'electric'
  // Catalogue growth: each a further original synthesis brief.
  | 'v6-na'
  | 'v6-turbo'
  | 'i5-turbo'
  | 'i6-turbo'
  | 'flat4-turbo'
  | 'flat12-na'
  | 'v12-turbo'
  | 'fuel-cell'
  | 'i3-bike'
  | 'two-stroke-bike'
  // Big-bore off-road V8: low revs, lumpy firing, a heavy dark voice.
  | 'v8-truck';

export interface SoundProfile {
  family: SoundFamily;
  /** Combustion events per crankshaft revolution (cylinders / 2 for four-stroke). */
  firingsPerRev: number;
  /** Harmonic band centres as fractions of the limiter. */
  bandCentres: readonly [number, number, number];
  bandWidth: number;
  bandGain: readonly [number, number, number];
  /** Spectral shape per band: odd-harmonic weight, every-third weight, roll-off. */
  odd: number;
  third: number;
  rolloff: number;
  /** Uneven firing (cross-plane V8, big-bang V4) adds sub-harmonic burble. */
  burble: number;
  turbo: { minHz: number; spanHz: number; gain: number; fromRPM: number } | null;
  /** Gear mesh whine per m/s of road speed; straight-cut boxes are louder. */
  whineHzPerMS: number;
  whineGain: number;
  /** Overrun crackle above this fraction of the limiter (Infinity: none). */
  crackleFraction: number;
  crackleMaxRate: number;
  /** Electric motor/inverter whine per m/s (0: none). */
  motorHzPerMS: number;
  motorGain: number;
  /** Load normaliser override (Nm); null uses the torque-curve peak. */
  loadTorqueNm: number | null;
  /** Deliberate loudness trim of the family against the designed engine level
   * (engine-loudness.ts): 0 dB for a combustion engine, negative for the quiet
   * electric families, positive for a big-bore truck. */
  levelDb: number;
}

const base = {
  bandCentres: [0.33, 0.62, 0.91] as const,
  bandWidth: 0.31,
  bandGain: [0.26, 0.22, 0.085] as const,
  odd: 0.35,
  third: 0.6,
  rolloff: 1.8,
  burble: 0,
  turbo: null,
  whineHzPerMS: 41,
  whineGain: 0.004,
  crackleFraction: Infinity,
  crackleMaxRate: 0,
  motorHzPerMS: 0,
  motorGain: 0,
  loadTorqueNm: null,
  levelDb: 0,
} satisfies Partial<SoundProfile>;

export const SOUND_PROFILES: Readonly<Record<SoundFamily, SoundProfile>> = Object.freeze({
  // The original APX-01 voice: values equal the former constants exactly.
  'v6-turbo-hybrid': {
    ...base,
    family: 'v6-turbo-hybrid',
    firingsPerRev: 3,
    bandCentres: [4500 / 13700, 8500 / 13700, 12500 / 13700],
    bandWidth: 4300 / 13700,
    turbo: { minHz: 2600, spanHz: 5400, gain: 0.022, fromRPM: 4000 },
    whineGain: 0.009,
    crackleFraction: 7500 / 13700,
    crackleMaxRate: 14,
    // Engine plus deployed motor torque reaches ~650 Nm at the crank.
    loadTorqueNm: 650,
  },
  'i4-turbo': {
    ...base,
    family: 'i4-turbo',
    firingsPerRev: 2,
    bandGain: [0.3, 0.2, 0.06],
    odd: 0.2,
    third: 0.8,
