    for (const voice of this.voices) {
      if (voice.id < 0)
        for (let id = 0; id < count; id++)
          if (this.selected[id] && !this.assigned[id]) {
            voice.id = id;
            this.assigned[id] = 1;
            break;
          }
      if (voice.id >= 0) Object.assign(voice, this.sources[voice.id]);
    }
    Object.assign(this.player, this.sources[0]);
  }
}

