    const stick = (def.stickFraction * delta + drift * dt) / mobility;
    const capacity =
      def.kind === 'locked'
        ? def.maxLocking
        : def.kind === 'torsen'
          ? (0.5 * Math.abs(input) * (def.biasRatio - 1)) / (def.biasRatio + 1)
          : def.preload + (input >= 0 ? def.powerLock : def.coastLock) * Math.abs(input);
