      line.centre,
      input,
      onPower,
      (omega[0] + omega[1]) * 0.5,
      (omega[2] + omega[3]) * 0.5,
      inertia[0] + inertia[1],
      inertia[2] + inertia[3],
      dt,
      CENTRE,
      reaction[0] + reaction[1],
      reaction[2] + reaction[3],
