      torque,
      onPower,
      omega[axle],
      omega[axle + 1],
      inertia[axle],
      inertia[axle + 1],
      dt,
      AXLE,
      reaction[axle],
      reaction[axle + 1],
    );
    out[axle] = AXLE.first;
    out[axle + 1] = AXLE.second;
  }
  return out;
}

